<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('commercial_manager');$user=current_user();$flashes=render_flashes();$currentPage='reports';$pageTitle='Commercial Reports';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$managerId=(int)($user['id']??$user['user_id']??0);$rows=[];
if(cm_table($conn,'commercial_capability_packs')){$s=$conn->prepare("SELECT cp.id,cp.pack_name,cp.tender_reference,cp.total_candidate_count,cp.suppressed_group_count,cp.taxonomy_version,cp.data_snapshot_at,cp.generated_at,ss.search_name FROM commercial_capability_packs cp JOIN commercial_saved_searches ss ON ss.id=cp.saved_search_id WHERE cp.commercial_manager_id=? ORDER BY cp.generated_at DESC");$s->bind_param('i',$managerId);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$rows[]=$x;$s->close();}
$total=count($rows);$capacity=array_sum(array_map(fn($x)=>(int)$x['total_candidate_count'],$rows));$supp=array_sum(array_map(fn($x)=>(int)$x['suppressed_group_count'],$rows));require __DIR__.'/_layout_start.php';?>
<div class="cm-page-header"><div><span>Commercial Intelligence</span><h2>Reports</h2><p>Capability-pack generation, represented capacity and suppression activity.</p></div></div><section class="cm-stats cm-stats--3"><article><i class="fas fa-file-shield"></i><strong><?= $total ?></strong><span>Capability Packs</span></article><article><i class="fas fa-users"></i><strong><?= number_format($capacity) ?></strong><span>Aggregate Capacity</span></article><article><i class="fas fa-eye-slash"></i><strong><?= number_format($supp) ?></strong><span>Suppressed Groups</span></article></section><div class="cm-card"><div class="cm-table-wrap"><table><thead><tr><th>Pack</th><th>Search</th><th>Capacity</th><th>Suppressed</th><th>Taxonomy</th><th>Currency</th><th></th></tr></thead><tbody><?php foreach($rows as $x):?><tr><td><strong><?= e($x['pack_name']) ?></strong></td><td><?= e($x['search_name']) ?></td><td><?= number_format((int)$x['total_candidate_count']) ?></td><td><?= number_format((int)$x['suppressed_group_count']) ?></td><td><?= e($x['taxonomy_version']) ?></td><td><?= e(cm_currency($x['data_snapshot_at'])) ?></td><td><a class="cm-icon-btn" href="<?= url('commercial_manager/pack_view.php?id='.(int)$x['id']) ?>"><i class="fas fa-arrow-right"></i></a></td></tr><?php endforeach;?></tbody></table></div></div>
<?php require __DIR__.'/_layout_end.php';?>